test('private dashboard renders supported records safely without browser token storage or legacy write controls',async t=>{const s=await setup(t);assert.equal(s.state.reads,1);assert.match(s.root.innerHTML,/Fictional task &lt;script&gt;/);assert.match(s.root.innerHTML,/Fictional private note/);assert.doesNotMatch(s.root.innerHTML,/<script>|brief-add-task|data-toggle|dev-organize.html|dev-account.html/);});
test('logout wipes private dashboard immediately and suppresses a pending response',async t=>{const s=await setup(t);let release;s.client.brief=()=>new Promise(resolve=>release=resolve);s.events.click({target:{closest:selector=>selector==='#private-brief-refresh'?{}:null}});while(!release)await turn();s.logout();assert.doesNotMatch(s.root.innerHTML,/Fictional private note|Fictional task/);release(structuredClone(data));for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/private-brief-login/);assert.doesNotMatch(s.root.innerHTML,/Fictional private note/);assert.equal(s.state.closed,1);});
test('failed private refresh clears stale records without reporting a fresh successful read',async t=>{const s=await setup(t);s.client.brief=async()=>{throw Error('Fictional offline read');};s.events.click({target:{closest:selector=>selector==='#private-brief-refresh'?{}:null}});for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/Fictional offline read/);assert.doesNotMatch(s.root.innerHTML,/Fictional private note|Saved workspace checked/);});
test('page hiding removes account and records; persisted page restoration rechecks the server',async t=>{const s=await setup(t);s.windowEvents.pagehide();assert.doesNotMatch(s.root.innerHTML,/fictional@example.test|Fictional private note/);s.windowEvents.pageshow({persisted:true});for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/Fictional private note/);assert.equal(s.state.reads,2);});

test('task completion requires separate review and approval; offline clears the review',async t=>{
 const s=await setup(t,{allowTaskCompletion:true});let reviews=0,writes=0;
 s.client.reviewCompletion=async()=>{reviews++;return{reviewId:'fictional-review',title:'Fictional completion',day:'2026-11-09',section:'Home',expiresAt:1000000};};
 s.client.approveCompletion=async()=>{writes++;return{completed:true};};
 const click=selector=>s.events.click({target:{closest:q=>q===selector?(selector==='[data-private-complete]'?{dataset:{privateComplete:'x'.repeat(43)}}:{}):null}});
 click('[data-private-complete]');for(let i=0;i<4;i++)await turn();assert.equal(reviews,1);assert.equal(writes,0);assert.match(s.root.innerHTML,/Approve completion/);
 s.windowEvents.offline();assert.doesNotMatch(s.root.innerHTML,/Approve completion/);click('#private-task-approve');await turn();assert.equal(writes,0);
 click('[data-private-complete]');for(let i=0;i<4;i++)await turn();click('#private-task-approve');for(let i=0;i<6;i++)await turn();assert.equal(writes,1);assert.match(s.root.innerHTML,/Task marked complete/);
});
test('uncertain completion clears actions and never retries automatically',async t=>{
 const s=await setup(t,{allowTaskCompletion:true});let writes=0;s.client.reviewCompletion=async()=>({reviewId:'review',title:'Fictional',expiresAt:1000000});s.client.approveCompletion=async()=>{writes++;throw Error('Completion may have completed. Fetch latest.');};
 s.events.click({target:{closest:q=>q==='[data-private-complete]'?{dataset:{privateComplete:'x'.repeat(43)}}:null}});for(let i=0;i<4;i++)await turn();s.events.click({target:{closest:q=>q==='#private-task-approve'?{}:null}});for(let i=0;i<4;i++)await turn();assert.equal(writes,1);assert.match(s.root.innerHTML,/may have completed/);assert.doesNotMatch(s.root.innerHTML,/Approve completion|Fictional private note/);
});

