test('a late selected note cannot reappear after logout',async t=>{const s=await setup(t,{allowNoteRead:true});let release;s.client.readNote=()=>new Promise(resolve=>release=resolve);s.events.click({target:{closest:q=>q==='[data-private-note]'?{dataset:{privateNote:'x'.repeat(43)}}:null}});s.logout();release({title:'Late note',body:'PRIVATE_LATE_BODY',readOnly:true,expiresAt:1000000});for(let i=0;i<4;i++)await turn();assert.doesNotMatch(s.root.innerHTML,/PRIVATE_LATE_BODY|Late note/);});

async function editableNote(t){const s=await setup(t,{allowNoteRead:true,allowNoteEdit:true});s.client.readNote=async()=>({title:'Original fictional note',body:'Original fictional text',readOnly:true,expiresAt:1000000});s.click=(selector,value)=>s.events.click({target:{closest:q=>q===selector?(value?{dataset:value}:{}):null}});s.click('[data-private-note]',{privateNote:'x'.repeat(43)});for(let i=0;i<4;i++)await turn();s.click('#private-note-edit');s.events.input({target:{name:'title',value:'Updated fictional note'}});s.events.input({target:{name:'body',value:'Updated fictional text <script>'}});s.review=()=>s.events.submit({target:{id:'private-note-editor'},preventDefault(){}});return s;}
test('note editor requires separate review and approval and preserves draft text on an uncertain save',async t=>{const s=await editableNote(t);let writes=0;s.client.reviewNote=async changes=>({reviewId:'fictional-review',title:changes.title,body:changes.body,expiresAt:1000000});s.client.saveNote=async()=>{writes++;throw Error('Note save may have completed. Keep your draft.');};s.review();for(let i=0;i<4;i++)await turn();assert.equal(writes,0);assert.match(s.root.innerHTML,/Approve note save/);s.click('#private-note-approve');for(let i=0;i<4;i++)await turn();assert.equal(writes,1);assert.match(s.root.innerHTML,/Updated fictional text &lt;script&gt;/);assert.match(s.root.innerHTML,/Keep your draft/);assert.doesNotMatch(s.root.innerHTML,/Approve note save/);s.review();await turn();assert.equal(writes,1);});
test('successful note save clears the submitted draft and verifies the latest list',async t=>{const s=await editableNote(t);s.client.reviewNote=async changes=>({reviewId:'fictional-review',title:changes.title,body:changes.body,expiresAt:1000000});s.client.saveNote=async()=>({saved:true});s.review();for(let i=0;i<4;i++)await turn();s.click('#private-note-approve');for(let i=0;i<6;i++)await turn();assert.match(s.root.innerHTML,/Note saved and checked/);assert.doesNotMatch(s.root.innerHTML,/private-note-editor|Updated fictional text/);assert.equal(s.state.reads,2);});
test('note drafts survive offline errors, block refresh and clear on hidden tabs',async t=>{const s=await editableNote(t);s.windowEvents.offline();assert.match(s.root.innerHTML,/Updated fictional text &lt;script&gt;/);s.click('#private-brief-refresh');await turn();assert.equal(s.state.reads,1);s.document.visibilityState='hidden';s.windowEvents.visibilitychange();assert.doesNotMatch(s.root.innerHTML,/Updated fictional text|Original fictional text|private-note-editor/);});

async function creationDraft(t){const s=await setup(t,{allowTaskCreate:true});s.click=selector=>s.events.click({target:{closest:q=>q===selector?{}:null}});s.click('#private-task-new');s.events.input({target:{name:'create-title',value:'Fictional new task'}});s.events.change({target:{name:'create-day',value:'2026-11-09'}});s.events.change({target:{name:'create-section',value:'Home'}});s.review=()=>s.events.submit({target:{id:'private-task-create-form'},preventDefault(){}});s.client.reviewNewTask=async values=>({reviewId:'fictional-review',...values,expiresAt:1000000});return s;}
test('new-task draft requires review and approval; a confirmed creation clears draft and checks saved tasks',async t=>{const s=await creationDraft(t);let writes=0;s.client.createTask=async()=>{writes++;return{created:true};};s.review();for(let i=0;i<4;i++)await turn();assert.equal(writes,0);assert.match(s.root.innerHTML,/Approve task creation/);s.click('#private-task-create-approve');for(let i=0;i<6;i++)await turn();assert.equal(writes,1);assert.match(s.root.innerHTML,/Task created and checked/);assert.doesNotMatch(s.root.innerHTML,/private-task-create-form/);assert.equal(s.state.reads,2);});
test('uncertain task creation retains and locks the draft instead of retrying',async t=>{const s=await creationDraft(t);let writes=0;s.client.createTask=async()=>{writes++;throw Error('Task may have been created. Check latest.');};s.review();for(let i=0;i<4;i++)await turn();s.click('#private-task-create-approve');for(let i=0;i<4;i++)await turn();assert.equal(writes,1);assert.match(s.root.innerHTML,/Fictional new task|Check latest/);assert.doesNotMatch(s.root.innerHTML,/Approve task creation/);s.review();await turn();assert.equal(writes,1);});
test('new-task drafts survive offline errors, block refresh and clear on sign-out',async t=>{const s=await creationDraft(t);s.windowEvents.offline();assert.match(s.root.innerHTML,/Fictional new task/);s.click('#private-brief-refresh');await turn();assert.equal(s.state.reads,1);s.logout();for(let i=0;i<4;i++)await turn();assert.doesNotMatch(s.root.innerHTML,/Fictional new task|private-task-create-form/);});

async function taskEditDraft(t){const s=await setup(t,{allowTaskEdit:true});s.client.brief=async()=>({...structuredClone(data),dueTasks:[{...data.dueTasks[0],editToken:'x'.repeat(43)}]});s.events.click({target:{closest:q=>q==='#private-brief-refresh'?{}:null}});for(let i=0;i<4;i++)await turn();s.events.click({target:{closest:q=>q==='[data-private-task-edit]'?{dataset:{privateTaskEdit:'x'.repeat(43)}}:null}});s.events.input({target:{name:'create-title',value:'Fictional edited task'}});s.events.change({target:{name:'create-day',value:'2026-11-10'}});s.client.reviewTaskEdit=async values=>({reviewId:'fictional-edit-review',title:values.title,day:values.day,section:values.section,expiresAt:1000000});s.review=()=>s.events.submit({target:{id:'private-task-create-form'},preventDefault(){}});s.approve=()=>s.events.click({target:{closest:q=>q==='#private-task-create-approve'?{}:null}});return s;}
test('task edits require review and approval before saving and clear confirmed drafts',async t=>{const s=await taskEditDraft(t);let writes=0;s.client.saveTaskEdit=async()=>{writes++;return{saved:true};};s.review();for(let i=0;i<4;i++)await turn();assert.equal(writes,0);assert.match(s.root.innerHTML,/Approve task changes/);s.approve();for(let i=0;i<6;i++)await turn();assert.equal(writes,1);assert.match(s.root.innerHTML,/Task changes saved and checked/);assert.doesNotMatch(s.root.innerHTML,/private-task-create-form/);});
test('an uncertain task edit keeps the draft locked until discard/latest and never auto-retries',async t=>{const s=await taskEditDraft(t);let writes=0;s.client.saveTaskEdit=async()=>{writes++;throw Error('Task edit may have completed. Check latest.');};s.review();for(let i=0;i<4;i++)await turn();s.approve();for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/Fictional edited task|Check latest/);assert.doesNotMatch(s.root.innerHTML,/Approve task changes/);s.review();await turn();assert.equal(writes,1);s.logout();for(let i=0;i<4;i++)await turn();assert.doesNotMatch(s.root.innerHTML,/Fictional edited task/);});

test('a peer sign-out clears private records and pending drafts without reading records or signing out another login',async t=>{const channel={postMessage(){},close(){}},s=await setup(t,{channel});channel.onmessage({data:{type:'ended'}});assert.doesNotMatch(s.root.innerHTML,/Fictional private note|fictional@example.test/);assert.match(s.root.innerHTML,/changed in another tab|Recheck sign-in/);assert.equal(s.state.closed,0);assert.equal(s.state.reads,1);});
test('local sign-out sends only a public session event and channel messages with unknown types are ignored',async t=>{const sent=[],channel={postMessage:value=>sent.push(value),close(){}},s=await setup(t,{channel});channel.onmessage({data:{type:'unrecognized',owner:'never use'}});assert.match(s.root.innerHTML,/Fictional private note/);s.logout();for(let i=0;i<4;i++)await turn();assert.equal(JSON.stringify(sent),JSON.stringify([{type:'ended'}]));});
test('passive checks never reload records and failure clears private views',async t=>{const s=await setup(t);let checks=0;s.client.check=async()=>{checks++;return{signedIn:true,user:{id:'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',email:'fictional@example.test'},expiresAt:1000000};};s.tick();for(let i=0;i<4;i++)await turn();assert.equal(checks,1);assert.equal(s.state.reads,1);assert.match(s.root.innerHTML,/Fictional private note/);s.client.check=async()=>{throw Error('Fictional offline verification');};s.tick();for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/sign-in could not be verified/);assert.doesNotMatch(s.root.innerHTML,/Fictional private note/);});
test('a passive check cannot resurrect an account after a peer sign-out',async t=>{const channel={postMessage(){},close(){}},s=await setup(t,{channel});let release;s.client.check=()=>new Promise(resolve=>release=resolve);s.tick();channel.onmessage({data:{type:'ended'}});release({signedIn:true,user:{id:'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',email:'fictional@example.test'},expiresAt:1000000});for(let i=0;i<4;i++)await turn();assert.doesNotMatch(s.root.innerHTML,/Fictional private note|fictional@example.test/);});
test('hidden tabs skip passive checks and an explicit recheck verifies the current sign-in before loading',async t=>{const channel={postMessage(){},close(){}},s=await setup(t,{channel});let checks=0;s.client.check=async()=>{checks++;return{};};s.document.visibilityState='hidden';s.tick();await turn();assert.equal(checks,0);channel.onmessage({data:{type:'changed'}});s.document.visibilityState='visible';s.events.click({target:{closest:q=>q==='#private-brief-recheck'?{}:null}});for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/Fictional private note/);assert.equal(s.state.reads,2);assert.doesNotMatch(s.root.innerHTML,/changed in another tab/);});

test('passive checks clear the view when the cookie now belongs to a different account',async t=>{const s=await setup(t);s.client.check=async()=>({signedIn:true,user:{id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',email:'other@example.test'},expiresAt:1000000});s.tick();for(let i=0;i<4;i++)await turn();assert.doesNotMatch(s.root.innerHTML,/Fictional private note|other@example.test|fictional@example.test/);assert.match(s.root.innerHTML,/sign-in could not be verified/);});

