function captureFocus(s){const focused=[];s.root.querySelector=selector=>({disabled:false,matches:()=>/ input$| select$/.test(selector),setAttribute(name,value){assert.equal(name,'tabindex');assert.equal(value,'-1');},focus(){focused.push(selector);}});return focused;}
