test('upcoming event display includes date/time, escapes titles and clears on sign-out',async t=>{const s=await setup(t);s.client.brief=async()=>({...structuredClone(data),counts:{...data.counts,upcomingEvents:23},upcomingEvents:[{title:'Fictional future <script>',day:'2026-11-10',time:'09:30'}]});s.events.click({target:{closest:q=>q==='#private-brief-refresh'?{}:null}});for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/Upcoming workspace events/);assert.match(s.root.innerHTML,/Showing 1 of 23/);assert.match(s.root.innerHTML,/Fictional future &lt;script&gt;/);assert.match(s.root.innerHTML,/2026-11-10 · 09:30/);assert.doesNotMatch(s.root.innerHTML,/<script>/);s.logout();assert.doesNotMatch(s.root.innerHTML,/Fictional future|Upcoming workspace events/);});
