test('browse controls send an explicit type without a query and focus results without opening note text',async t=>{const s=await setup(t,{allowSearch:true,allowNoteRead:true}),focused=captureFocus(s),calls=[];s.client.search=async values=>{calls.push(values);return{...values,readOnly:true,providerRead:false,checkedAt:'2026-11-09T12:00:00Z',matchCount:1,results:[{type:values.type,title:'Fictional browsed <script>',section:'Personal Life'}]};};s.client.readNote=async()=>{throw Error('Browsing must not open text');};for(const type of ['task','note','event']){s.events.click({target:{closest:q=>q==='[data-private-browse]'?{dataset:{privateBrowse:type}}:null}});for(let i=0;i<4;i++)await turn();assert.equal(calls.at(-1).query,'');assert.equal(calls.at(-1).type,type);assert.equal(calls.at(-1).section,'all');assert.match(s.root.innerHTML,/All saved/);assert.match(s.root.innerHTML,/Fictional browsed &lt;script&gt;/);assert.equal(focused.at(-1),'#private-search-results-title');}s.logout();assert.doesNotMatch(s.root.innerHTML,/Fictional browsed|Browse tasks/);});
