test('typed task status is sent with blank task browse and reset when changing away from tasks',async t=>{const s=await setup(t,{allowSearch:true}),calls=[];s.client.search=async values=>{calls.push(values);return{...values,readOnly:true,providerRead:false,checkedAt:'2026-11-09T12:00:00Z',matchCount:0,results:[]};};for(const [name,value]of [['search-type','task'],['search-status','completed']])s.events.input({target:{name,value}});s.events.submit({target:{id:'private-title-search'},preventDefault(){}});for(let i=0;i<4;i++)await turn();assert.equal(calls[0].status,'completed');assert.equal(calls[0].query,'');assert.match(s.root.innerHTML,/Completed tasks/);s.events.input({target:{name:'search-type',value:'note'}});s.events.submit({target:{id:'private-title-search'},preventDefault(){}});for(let i=0;i<4;i++)await turn();assert.equal(calls[1].type,'note');assert.equal(calls[1].status,'all');});
test('clear search removes prior results and returns focus without reloading or opening text',async t=>{const s=await searchableBrief(t),focused=captureFocus(s);let searches=0;s.client.search=async()=>{searches++;return s.result;};s.search();for(let i=0;i<4;i++)await turn();const reads=s.state.reads;s.events.click({target:{closest:q=>q==='#private-search-clear'?{}:null}});assert.doesNotMatch(s.root.innerHTML,/Title search results|Fictional result/);assert.match(s.root.innerHTML,/Fictional private note/);assert.equal(searches,1);assert.equal(s.state.reads,reads);assert.equal(focused.at(-1),'[name="search-query"]');});

