test('reopening stays unavailable without its flag and an uncertain save never retries',async t=>{const off=await setup(t,{allowTaskCompletion:true});let reads=0;off.client.reviewCompletion=async()=>{reads++;};off.events.click({target:{closest:q=>q==='[data-private-reopen]'?{dataset:{privateReopen:'x'.repeat(43)}}:null}});assert.equal(reads,0);const s=await setup(t,{allowTaskCompletion:true,allowTaskReopen:true});let writes=0;s.client.reviewCompletion=async()=>({reviewId:'fictional',reopening:true,title:'Fictional',day:'2026-11-09',section:'Home',expiresAt:1000000});s.client.approveCompletion=async()=>{writes++;throw Error('Reopening may have completed. Fetch latest.');};const click=q=>s.events.click({target:{closest:selector=>selector===q?(q==='[data-private-reopen]'?{dataset:{privateReopen:'x'.repeat(43)}}:{}):null}});click('[data-private-reopen]');for(let i=0;i<4;i++)await turn();click('#private-task-approve');for(let i=0;i<4;i++)await turn();click('#private-task-approve');assert.equal(writes,1);assert.doesNotMatch(s.root.innerHTML,/Approve reopening/);assert.match(s.root.innerHTML,/may have completed/);});

test('completed search results expose reopening only under its flag and still require explicit approval',async t=>{const s=await setup(t,{allowSearch:true,allowTaskCompletion:true,allowTaskReopen:true});let writes=0;s.client.search=async values=>({...values,readOnly:true,providerRead:false,checkedAt:'2026-11-09T12:00:00Z',matchCount:1,results:[{type:'task',completed:true,title:'Fictional searched completed',day:'2026-11-08',section:'Home',reopenToken:'r'.repeat(43)}]});s.client.reviewCompletion=async token=>{assert.equal(token,'r'.repeat(43));return{reviewId:'fictional-review',reopening:true,title:'Fictional searched completed',day:'2026-11-08',section:'Home',expiresAt:1000000};};s.client.approveCompletion=async()=>{writes++;return{reopened:true};};s.events.click({target:{closest:q=>q==='[data-private-browse]'?{dataset:{privateBrowse:'task'}}:null}});for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/data-private-reopen="r{43}"/);assert.doesNotMatch(s.root.innerHTML,/data-private-complete="r{43}"/);s.events.click({target:{closest:q=>q==='[data-private-reopen]'?{dataset:{privateReopen:'r'.repeat(43)}}:null}});for(let i=0;i<4;i++)await turn();assert.equal(writes,0);assert.match(s.root.innerHTML,/Approve reopening/);s.events.click({target:{closest:q=>q==='#private-task-approve'?{}:null}});for(let i=0;i<6;i++)await turn();assert.equal(writes,1);assert.match(s.root.innerHTML,/Task reopened/);assert.doesNotMatch(s.root.innerHTML,/Fictional searched completed/);});

