test('uncertain note draft has escaped selectable text without saving, clipboard access or opaque handles',async t=>{const s=await noteCreationDraft(t);let writes=0;s.client.createNote=async()=>{writes++;throw Error('Fictional uncertain note save');};s.review();for(let i=0;i<4;i++)await turn();s.click('#private-note-approve');for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/Copy your draft/);assert.match(s.root.innerHTML,/<textarea id="private-draft-copy" readonly/);assert.match(s.root.innerHTML,/Title: Fictional new note\n\nFictional new text &lt;script&gt;/);assert.doesNotMatch(s.root.innerHTML,/<script>/);let focused=0,selected=0;s.root.querySelector=selector=>{assert.equal(selector,'#private-draft-copy');return{focus(){focused++;},select(){selected++;}};};s.click('#private-draft-select');assert.equal(focused,1);assert.equal(selected,1);assert.equal(writes,1);s.review();await turn();assert.equal(writes,1);s.windowEvents.pagehide();assert.doesNotMatch(s.root.innerHTML,/Copy your draft|Fictional new text/);});
