test('event edits can open from search without granting event handles to task controls',async t=>{const s=await setup(t,{allowSearch:true,allowEventEdit:true,allowTaskEdit:true});s.client.search=async values=>({...values,readOnly:true,providerRead:false,checkedAt:'2026-11-09T12:00:00Z',matchCount:1,results:[{type:'event',title:'Fictional searched event',day:'2026-11-10',time:'11:00',section:'Calendar',eventEditToken:'e'.repeat(43)}]});s.events.click({target:{closest:q=>q==='[data-private-browse]'?{dataset:{privateBrowse:'event'}}:null}});for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/data-private-event-edit="e{43}"/);assert.doesNotMatch(s.root.innerHTML,/data-private-task-edit="e{43}"/);s.client.readEventEdit=async()=>({title:'Fictional searched event',day:'2026-11-10',time:'11:00',end_time:'',section:'Calendar',expiresAt:1000000});s.events.click({target:{closest:q=>q==='[data-private-event-edit]'?{dataset:{privateEventEdit:'e'.repeat(43)}}:null}});for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/Edit this workspace event/);assert.match(s.root.innerHTML,/value="2026-11-10"/);assert.match(s.root.innerHTML,/value="11:00"/);});

test('event end time is loaded before editing and explicitly included in reviewed changes',async t=>{const s=await editableEvent(t);s.client.cancelEventEdit=async()=>({cancelled:true});s.click('#private-task-create-discard');for(let i=0;i<4;i++)await turn();s.client.readEventEdit=async()=>({title:'Fictional original event',day:data.day,time:'09:30',end_time:'11:00',section:'Calendar',expiresAt:1000000});s.click('[data-private-event-edit]',{privateEventEdit:'v'.repeat(43)});for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/Event end time \(same date, optional\)/);assert.match(s.root.innerHTML,/value="11:00"/);s.events.input({target:{name:'create-end_time',value:'12:00'}});let proposed;s.client.reviewEventEdit=async values=>{proposed=values;return{...values,section:'Calendar',reviewId:'fictional',expiresAt:1000000};};s.review();for(let i=0;i<4;i++)await turn();assert.equal(proposed.end_time,'12:00');assert.match(s.root.innerHTML,/09:30–12:00 New York time/);});
test('sign-out suppresses a delayed event-fields response without exposing an editor',async t=>{const s=await setup(t,{allowEventEdit:true,allowSearch:true});s.client.search=async values=>({...values,readOnly:true,providerRead:false,checkedAt:'2026-11-09T12:00:00Z',matchCount:1,results:[{type:'event',title:'Fictional event',day:data.day,time:'09:00',section:'Calendar',eventEditToken:'e'.repeat(43)}]});s.events.click({target:{closest:q=>q==='[data-private-browse]'?{dataset:{privateBrowse:'event'}}:null}});for(let i=0;i<4;i++)await turn();let release;s.client.readEventEdit=()=>new Promise(resolve=>release=resolve);s.events.click({target:{closest:q=>q==='[data-private-event-edit]'?{dataset:{privateEventEdit:'e'.repeat(43)}}:null}});s.logout();release({title:'Fictional event',day:data.day,time:'09:00',end_time:'11:00',section:'Calendar',expiresAt:1000000});for(let i=0;i<4;i++)await turn();assert.doesNotMatch(s.root.innerHTML,/Event end time|Edit this workspace event|value="11:00"/);});

test('new workspace event includes optional end time in explicit review and verified creation',async t=>{const s=await eventDraft(t);s.events.input({target:{name:'create-end_time',value:'15:30'}});let proposed,writes=0;s.client.reviewNewEvent=async values=>{proposed=values;return{...values,section:'Calendar',reviewId:'fictional',expiresAt:1000000};};s.client.createEvent=async()=>{writes++;return{created:true};};s.review();for(let i=0;i<4;i++)await turn();assert.equal(proposed.end_time,'15:30');assert.equal(writes,0);assert.match(s.root.innerHTML,/14:30–15:30 New York time/);s.click('#private-task-create-approve');for(let i=0;i<6;i++)await turn();assert.equal(writes,1);assert.match(s.root.innerHTML,/Workspace event created and checked/);assert.doesNotMatch(s.root.innerHTML,/private-task-create-form/);});

test('Brief and browsing render sanitized event ranges and unavailable-end labels, then clear on sign-out',async t=>{const s=await setup(t,{allowSearch:true});s.client.brief=async()=>({...structuredClone(data),counts:{...data.counts,eventsToday:1,upcomingEvents:1},eventsToday:[{title:'Fictional duration',time:'10:30',endTime:'11:30'}],upcomingEvents:[{title:'Fictional unavailable end',day:'2026-11-10',time:'09:00',endTimeUnavailable:true}]});s.events.click({target:{closest:q=>q==='#private-brief-refresh'?{}:null}});for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/10:30–11:30/);assert.match(s.root.innerHTML,/09:00 · End time unavailable/);s.client.search=async values=>({...values,readOnly:true,providerRead:false,checkedAt:'2026-11-09T12:00:00Z',matchCount:1,results:[{type:'event',title:'Fictional searched duration',day:'2026-11-10',time:'12:00',endTime:'13:00',section:'Calendar'}]});s.events.click({target:{closest:q=>q==='[data-private-browse]'?{dataset:{privateBrowse:'event'}}:null}});for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/12:00–13:00/);s.logout();assert.doesNotMatch(s.root.innerHTML,/Fictional duration|Fictional searched duration|End time unavailable/);});

