test('mismatched checklist statuses in review cannot be approved',async t=>{const s=await checklistEditDraft(t);s.client.reviewTaskEdit=async fields=>({...fields,reviewId:'fixture',subtasks:[{title:'First <script>',done:true},{title:'Second',done:true}],expiresAt:1000000});s.review();for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/Checklist changes could not be verified/);assert.doesNotMatch(s.root.innerHTML,/Approve task changes/);});

test('task completion/reopening review explains remaining steps without changing or automatically approving anything',async t=>{for(const reopening of [false,true]){const s=await setup(t,{allowTaskCompletion:true,allowTaskReopen:true});s.client.reviewCompletion=async()=>({title:'Fictional task',reviewId:'fixture',expiresAt:1000000,reopening,checklist:{total:3,open:2}});let writes=0;s.client.approveCompletion=async()=>{writes++;return{completed:true};};s.events.click({target:{closest:q=>q===(reopening?'[data-private-reopen]':'[data-private-complete]')?{dataset:{privateReopen:'x'.repeat(43),privateComplete:'x'.repeat(43)}}:null}});for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/2 of 3 checklist steps remain open/);assert.match(s.root.innerHTML,reopening?/Reopening the task leaves each step unchanged/:/Completing the task leaves each step unchanged/);assert.equal(writes,0);}});
