test('Escape closes selected read-only notes and preserves active editors',async t=>{const s=await setup(t,{allowNoteRead:true});s.client.readNote=async()=>({title:'Fictional selected note',body:'TEMPORARY_NOTE_BODY',readOnly:true,expiresAt:1000000});s.events.click({target:{closest:q=>q==='[data-private-note]'?{dataset:{privateNote:'x'.repeat(43)}}:null}});for(let i=0;i<4;i++)await turn();let prevented=false;s.windowEvents.keydown({key:'Escape',preventDefault(){prevented=true;}});assert.equal(prevented,true);assert.doesNotMatch(s.root.innerHTML,/TEMPORARY_NOTE_BODY/);const editor=await editableNote(t);editor.windowEvents.keydown({key:'Escape',preventDefault(){throw Error('Must not discard an editor');}});assert.match(editor.root.innerHTML,/private-note-editor/);});

