test('mismatched removal review cannot be approved',async t=>{const s=await checklistEditDraft(t,{structure:true});s.client.reviewTaskEdit=async fields=>({...fields,subtasks:[{title:'First <script>',done:false},{title:'Second',done:true}],removedSubtasks:[{title:'Unexpected',done:true}],addedSubtaskCount:0,reviewId:'fixture',expiresAt:1000000});s.review();for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/additions or removals could not be verified/);assert.doesNotMatch(s.root.innerHTML,/Approve task changes/);});

