test('uncertain recovery save clears stale records and never offers automatic retry',async t=>{const s=await setup(t,{allowRecentlyDeleted:true});s.client.reviewRecord=async()=>({reviewId:'r'.repeat(43),title:'Fictional removal',type:'note',section:'Personal Life',restoring:false,retentionDays:90,expiresAt:100000});let writes=0;s.client.saveRecord=async()=>{writes++;throw Error('Change may have completed. Fetch latest.');};const click=selector=>s.events.click({target:{closest:q=>q===selector?(selector==='[data-private-record-review]'?{dataset:{privateRecordReview:'t'.repeat(43)}}:{}):null}});click('[data-private-record-review]');for(let i=0;i<4;i++)await turn();click('#private-record-approve');for(let i=0;i<4;i++)await turn();click('#private-record-approve');assert.equal(writes,1);assert.match(s.root.innerHTML,/Change may have completed/);assert.doesNotMatch(s.root.innerHTML,/Fictional private note|Approve removal/);});

test('cancelling a removal review rechecks Brief actions instead of leaving retired capabilities',async t=>{const s=await setup(t,{allowRecentlyDeleted:true});s.client.reviewRecord=async()=>({reviewId:'r'.repeat(43),title:'Fictional removal',type:'task',section:'Work',restoring:false,retentionDays:90,expiresAt:100000});let cancelled=0;s.client.cancelRecord=async()=>{cancelled++;return{cancelled:true};};const click=selector=>s.events.click({target:{closest:q=>q===selector?(selector==='[data-private-record-review]'?{dataset:{privateRecordReview:'t'.repeat(43)}}:{}):null}});click('[data-private-record-review]');for(let i=0;i<4;i++)await turn();const reads=s.state.reads;click('#private-record-cancel');for(let i=0;i<8;i++)await turn();assert.equal(cancelled,1);assert.equal(s.state.reads,reads+1);assert.doesNotMatch(s.root.innerHTML,/Approve removal/);});

test('Brief date browsing is explicit, validates before a read and labels current records rather than snapshots',async t=>{const off=await setup(t);assert.doesNotMatch(off.root.innerHTML,/private-brief-date-form/);const s=await setup(t,{allowBriefDates:true});assert.match(s.root.innerHTML,/not a historical snapshot/);const days=[];s.client.brief=async day=>{days.push(day);return{...structuredClone(data),day:day||'2026-11-09',...(day?{selectedDate:true,currentRecords:true}:{})};};s.events.input({target:{name:'brief-date',value:'2026-02-29'}});await s.events.submit({target:{id:'private-brief-date-form'},preventDefault(){}});await turn();assert.equal(days.length,0);assert.match(s.root.innerHTML,/Choose a valid date/);s.events.input({target:{name:'brief-date',value:'2026-11-08'}});await s.events.submit({target:{id:'private-brief-date-form'},preventDefault(){}});for(let i=0;i<4;i++)await turn();assert.deepEqual(days,['2026-11-08']);assert.match(s.root.innerHTML,/For 2026-11-08/);assert.match(s.root.innerHTML,/Workspace events on 2026-11-08/);assert.doesNotMatch(s.root.innerHTML,/Today’s workspace events/);assert.doesNotMatch(s.root.innerHTML,/The New York date has changed/);s.events.click({target:{closest:q=>q==='#private-brief-next-day'?{}:null}});for(let i=0;i<4;i++)await turn();assert.equal(days.at(-1),'2026-11-09');s.events.click({target:{closest:q=>q==='#private-brief-today'?{}:null}});for(let i=0;i<4;i++)await turn();assert.equal(days.at(-1),undefined);});
test('date navigation preserves an open task draft and rejects mismatched or late responses',async t=>{const s=await setup(t,{allowBriefDates:true,allowTaskCreate:true});s.events.click({target:{closest:q=>q==='#private-task-new'?{}:null}});let reads=0;s.client.brief=async()=>{reads++;return{...structuredClone(data),...(allowUndatedTasks?{undatedTasks:[],counts:{...data.counts,undatedTasks:0}}:{})};};s.events.click({target:{closest:q=>q==='#private-brief-next-day'?{}:null}});await turn();assert.equal(reads,0);assert.match(s.root.innerHTML,/private-task-create-form/);const other=await setup(t,{allowBriefDates:true});other.client.brief=async()=>({...structuredClone(data),selectedDate:true,currentRecords:true});other.events.click({target:{closest:q=>q==='#private-brief-next-day'?{}:null}});for(let i=0;i<4;i++)await turn();assert.match(other.root.innerHTML,/selected Brief date could not be verified/);assert.doesNotMatch(other.root.innerHTML,/Fictional private note/);});

