async function selectedCopyTask(t,patch={},options={}){const s=await setup(t,{...taskCopyOptions,...options});s.selectedCopyView={readOnly:true,expiresAt:1000000,title:'Fictional reusable plan <script>',day:'2026-11-10',section:'Work',priority:'Urgent',completed:true,description:'Fictional reusable instructions',subtasks:[{title:'First copied step',done:true},{title:'Second copied step',done:false}],subtaskCount:2,omittedSubtasks:0,...patch};s.client.readTask=async()=>structuredClone(s.selectedCopyView);s.events.click({target:{closest:q=>q==='[data-private-task-open]'?{dataset:{privateTaskOpen:'Q'.repeat(43)}}:null}});for(let i=0;i<4;i++)await turn();return s;}
test('copying selected completed task prepares an editable new draft without a request or source edit',async t=>{const s=await selectedCopyTask(t),before=structuredClone(s.selectedCopyView);let reviews=0;s.client.reviewNewTask=async()=>{reviews++;throw Error('Not expected during copy');};s.events.click({target:{closest:q=>q==='#private-task-copy'?{}:null}});assert.match(s.root.innerHTML,/id="private-task-create-form"/);assert.match(s.root.innerHTML,/Fictional reusable plan &lt;script&gt;/);assert.match(s.root.innerHTML,/First copied step\nSecond copied step/);assert.match(s.root.innerHTML,/all new checklist steps start open/);assert.match(s.root.innerHTML,/The original is unchanged/);assert.doesNotMatch(s.root.innerHTML,/<script>|private-task-details-title/);assert.equal(reviews,0);assert.deepEqual(s.selectedCopyView,before);});
test('copied task creation still has separate review, approval and freshly open steps',async t=>{const s=await selectedCopyTask(t);let reviews=0,writes=0;s.client.reviewNewTask=async fields=>{reviews++;assert.equal(fields.title,s.selectedCopyView.title);assert.equal(fields.day,s.selectedCopyView.day);assert.equal(fields.priority,'Urgent');assert.deepEqual(Array.from(fields.subtasks),['First copied step','Second copied step']);assert.equal(Object.hasOwn(fields,'editToken'),false);return{...fields,subtasks:fields.subtasks.map(title=>({title,done:false})),reviewId:'copy-review',expiresAt:1000000};};s.client.createTask=async()=>{writes++;return{created:true};};s.events.click({target:{closest:q=>q==='#private-task-copy'?{}:null}});s.events.submit({target:{id:'private-task-create-form'},preventDefault(){}});for(let i=0;i<4;i++)await turn();assert.equal(reviews,1);assert.equal(writes,0);assert.match(s.root.innerHTML,/private-task-create-approve/);s.events.click({target:{closest:q=>q==='#private-task-create-approve'?{}:null}});for(let i=0;i<8;i++)await turn();assert.equal(writes,1);assert.doesNotMatch(s.root.innerHTML,/New task draft prepared from the displayed task/);});
test('incomplete or oversized selected task never creates a partial copied draft',async t=>{for(const patch of [{description:'x'.repeat(1001)},{omittedSubtasks:1,subtaskCount:3}]){const s=await selectedCopyTask(t,patch);s.events.click({target:{closest:q=>q==='#private-task-copy'?{}:null}});assert.match(s.root.innerHTML,/Nothing was copied/);assert.doesNotMatch(s.root.innerHTML,/id="private-task-create-form"/);assert.match(s.root.innerHTML,/private-task-details-title/);}});
test('copied drafts warn before leaving and clear completely at sign-out',async t=>{const s=await selectedCopyTask(t);s.events.click({target:{closest:q=>q==='#private-task-copy'?{}:null}});let warned=0;s.windowEvents.beforeunload({preventDefault(){warned++;}});assert.equal(warned,1);s.logout();assert.doesNotMatch(s.root.innerHTML,/Fictional reusable instructions|First copied step|New task draft prepared/);});
test('explicit long-description mode copies complete selected text and sends it only on review',async t=>{const description='Long fictional instructions <script>\n'+'x'.repeat(9963),s=await selectedCopyTask(t,{description},{allowLongTaskDescriptions:true});assert.equal(description.length,10000);let requests=0;s.client.reviewNewTask=async fields=>{requests++;assert.equal(fields.description,description);return{...fields,subtasks:fields.subtasks.map(title=>({title,done:false})),reviewId:'long-review',expiresAt:1000000};};s.events.click({target:{closest:q=>q==='#private-task-copy'?{}:null}});assert.match(s.root.innerHTML,/maxlength="10000"/);assert.doesNotMatch(s.root.innerHTML,/<script>/);assert.equal(requests,0);s.events.submit({target:{id:'private-task-create-form'},preventDefault(){}});for(let i=0;i<4;i++)await turn();assert.equal(requests,1);assert.match(s.root.innerHTML,/private-task-create-approve/);});
