test('reviewed Brief layout persists order and presentation without changing source records or applying an unapproved draft',async t=>{
 const s=await setup(t,{allowBriefLayout:true});let proposed,writes=0;
 s.client.briefLayoutReview=async({layout})=>{proposed=structuredClone(layout);return{layout,reviewId:'R'.repeat(43),expiresAt:300001};};s.client.briefLayoutSave=async()=>{writes++;s.state.briefLayout=structuredClone(proposed);return{saved:true,layout:proposed};};
 const click=(selector,dataset={})=>s.events.click({target:{closest:q=>q===selector?{dataset}:null}});
 const before=s.root.innerHTML;assert.ok(before.indexOf('<h2>Due and overdue tasks</h2>')<before.indexOf('<h2>Recent note titles</h2>'));click('#private-brief-layout-open');for(let n=0;n<4;n++)await turn();
 for(let n=0;n<6;n++)click('[data-brief-layout-up]',{briefLayoutUp:'notes'});s.events.input({target:{name:'brief-layout-display-dueTasks',value:'hidden'}});s.events.input({target:{name:'brief-layout-display-completedTasks',value:'expanded'}});assert.match(s.root.innerHTML,/Fictional task &lt;script&gt;/);assert.equal(writes,0);
 click('#private-brief-layout-review');for(let n=0;n<4;n++)await turn();assert.match(s.root.innerHTML,/Review Daily Brief layout/);assert.equal(writes,0);click('#private-brief-layout-approve');for(let n=0;n<8;n++)await turn();assert.equal(writes,1);assert.equal(s.state.briefLayout.sections[0].id,'notes');assert.match(s.root.innerHTML,/<h2>Recent note titles<\/h2>/);assert.doesNotMatch(s.root.innerHTML,/Fictional task &lt;script&gt;|<h2>Due and overdue tasks<\/h2>/);assert.match(s.root.innerHTML,/<h2>Completed tasks<\/h2>/);
 click('#private-brief-refresh');for(let n=0;n<6;n++)await turn();assert.doesNotMatch(s.root.innerHTML,/<h2>Due and overdue tasks<\/h2>/);assert.match(s.root.innerHTML,/Fictional private note/);assert.equal(writes,1);
});
