test('Calendar navigation rejects an open range without a request or losing input and cannot interrupt an event draft',async t=>{const s=await setup(t,{...calendarOptions,allowEventCreate:true});let calls=0;const original=s.client.calendar;s.client.calendar=f=>{calls++;return original(f);};s.events.input({target:{name:'search-dateFrom',value:''}});clickCalendar(s,'next');for(let i=0;i<4;i++)await turn();assert.equal(calls,0);assert.match(s.root.innerHTML,/Choose both dates in order/);clickCalendar(s,'month');for(let i=0;i<4;i++)await turn();assert.equal(calls,1);assert.match(s.root.innerHTML,/value="2026-11-01"/);assert.match(s.root.innerHTML,/value="2026-11-30"/);s.events.click({target:{closest:q=>q==='#private-event-new'?{}:null}});s.events.input({target:{name:'create-title',value:'Retain this draft'}});clickCalendar(s,'today');for(let i=0;i<4;i++)await turn();assert.equal(calls,1);assert.match(s.root.innerHTML,/private-task-create-form/);assert.match(s.root.innerHTML,/value="2026-11-01"/);});
const copyEventOptions={...calendarOptions,allowEventCreate:true,allowAllDayEvents:true,allowEventRanges:true};
async function openCopyEvent(s){s.client.readEventEdit=async()=>({title:'Fictional workspace event',day:'2026-11-01',time:'09:00',end_time:'10:00',end_day:'',all_day:false,section:'Calendar',location:'Fictional room',description:'Fictional complete details',expiresAt:copyEventOptions.clock()+100000});s.events.click({target:{closest:q=>q==='[data-private-event-open]'?{dataset:{privateEventOpen:'E'.repeat(43)}}:null}});for(let i=0;i<4;i++)await turn();}
const clickEventCopy=s=>s.events.click({target:{closest:q=>q==='#private-event-copy'?{}:null}});
test('copying an explicitly opened event prepares an editable draft without reading or saving again',async t=>{const s=await setup(t,copyEventOptions);await openCopyEvent(s);assert.match(s.root.innerHTML,/Copy to a new event/);s.client.readEventEdit=()=>{throw Error('No extra read');};clickEventCopy(s);assert.match(s.root.innerHTML,/New event draft prepared/);assert.match(s.root.innerHTML,/value="Fictional room"/);assert.match(s.root.innerHTML,/Fictional complete details/);assert.doesNotMatch(s.root.innerHTML,/id="private-event-details-title"|Edit this workspace event/);let warned=false;s.windowEvents.beforeunload({preventDefault(){warned=true;}});assert.equal(warned,true);s.logout();for(let i=0;i<4;i++)await turn();assert.doesNotMatch(s.root.innerHTML,/Fictional complete details|New event draft prepared/);});
test('copied event still requires a distinct creation review and explicit approval',async t=>{const s=await setup(t,copyEventOptions);await openCopyEvent(s);let reviews=0,saves=0;s.client.reviewNewEvent=async fields=>{reviews++;assert.equal(fields.editToken,undefined);return{...fields,section:'Calendar',reviewId:'copy-review',expiresAt:copyEventOptions.clock()+100000};};s.client.createEvent=async id=>{assert.equal(id,'copy-review');saves++;return{created:true};};clickEventCopy(s);assert.equal(reviews,0);assert.equal(saves,0);s.events.submit({target:{id:'private-task-create-form'},preventDefault(){}});for(let i=0;i<4;i++)await turn();assert.equal(reviews,1);assert.equal(saves,0);s.events.click({target:{closest:q=>q==='#private-task-create-approve'?{}:null}});for(let i=0;i<8;i++)await turn();assert.equal(saves,1);assert.match(s.root.innerHTML,/Workspace event created and checked/);});
test('event copy is unavailable without complete creation/range scope and refuses stale opened data',async t=>{const off=await setup(t,calendarOptions);await openCopyEvent(off);assert.doesNotMatch(off.root.innerHTML,/id="private-event-copy"/);let clock=copyEventOptions.clock();const s=await setup(t,{...copyEventOptions,clock:()=>clock});await openCopyEvent(s);clock+=200000;clickEventCopy(s);assert.match(s.root.innerHTML,/Open a fresh event view/);assert.doesNotMatch(s.root.innerHTML,/id="private-task-create-form"/);});
test('unconfirmed copied-event creation retains its draft and never automatically retries',async t=>{const s=await setup(t,copyEventOptions);await openCopyEvent(s);s.client.reviewNewEvent=async f=>({...f,section:'Calendar',reviewId:'copy-review',expiresAt:copyEventOptions.clock()+100000});let saves=0;s.client.createEvent=async()=>{saves++;throw Error('Save confirmation unavailable');};clickEventCopy(s);s.events.submit({target:{id:'private-task-create-form'},preventDefault(){}});for(let i=0;i<4;i++)await turn();s.events.click({target:{closest:q=>q==='#private-task-create-approve'?{}:null}});for(let i=0;i<4;i++)await turn();assert.equal(saves,1);assert.match(s.root.innerHTML,/Save confirmation unavailable|Fictional complete details/);s.events.click({target:{closest:q=>q==='#private-task-create-approve'?{}:null}});for(let i=0;i<4;i++)await turn();assert.equal(saves,1);assert.match(s.root.innerHTML,/private-draft-copy/);});
test('a signed-out recheck clears private data and drafts immediately without another record request',async t=>{const s=await setup(t,{allowTaskCreate:true});s.events.click({target:{closest:q=>q==='#private-task-new'?{}:null}});s.events.input({target:{name:'create-title',value:'Private retained draft'}});const before=s.state.reads;s.client.status=async()=>({signedIn:false});s.windowEvents.pageshow({persisted:true});for(let i=0;i<4;i++)await turn();assert.equal(s.state.reads,before);assert.match(s.root.innerHTML,/private-brief-login/);assert.doesNotMatch(s.root.innerHTML,/Private retained draft|Fictional private note|Fictional task/);});
test('a same-account sign-in recheck preserves and reenables an existing draft without fetching records',async t=>{const s=await setup(t,{allowTaskCreate:true});s.events.click({target:{closest:q=>q==='#private-task-new'?{}:null}});s.events.input({target:{name:'create-title',value:'Preserve on recheck'}});const before=s.state.reads;s.windowEvents.pageshow({persisted:true});for(let i=0;i<4;i++)await turn();assert.equal(s.state.reads,before);assert.match(s.root.innerHTML,/value="Preserve on recheck"/);assert.doesNotMatch(s.root.innerHTML,/value="Preserve on recheck" disabled/);});
test('a different verified account cannot inherit an existing draft or appearance',async t=>{const s=await setup(t,{allowTaskCreate:true});s.events.click({target:{closest:q=>q==='#private-task-new'?{}:null}});s.events.input({target:{name:'create-title',value:'Original account draft'}});s.client.status=async()=>({signedIn:true,user:{id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',email:'other@example.test'},expiresAt:999999});s.client.brief=async()=>({...structuredClone(data),notes:[],dueTasks:[],expiresAt:999999});s.windowEvents.pageshow({persisted:true});for(let i=0;i<4;i++)await turn();assert.doesNotMatch(s.root.innerHTML,/Original account draft|Fictional private note|Fictional task/);assert.match(s.root.innerHTML,/other@example.test/);});
test('malformed or expired restored sign-in clears the old view and never fetches app records',async t=>{for(const patch of [{signedIn:'true'},{signedIn:true,user:{id:'bad'},expiresAt:999999},{signedIn:true,expiresAt:1}]){const s=await setup(t);const before=s.state.reads;s.client.status=async()=>patch;s.windowEvents.pageshow({persisted:true});for(let i=0;i<4;i++)await turn();assert.equal(s.state.reads,before);assert.match(s.root.innerHTML,/Private sign-in could not be verified/);assert.doesNotMatch(s.root.innerHTML,/Fictional private note|Fictional task/);}});
