test('task date shortcuts preserve title/section/priority, make Overdue open-only and clear undated bounds',async t=>{const s=await setup(t,taskSpaceOptions),calls=[];s.client.search=async f=>{calls.push({...f});return{...f,limit:50,offset:0,matchCount:0,omittedRecords:0,dateRangeUnavailableRecords:0,readOnly:true,providerRead:false,checkedAt:new Date(Date.parse('2026-11-10T18:00:00Z')).toISOString(),expiresAt:Date.parse('2026-11-10T19:00:00Z'),results:[]};};const click=action=>s.events.click({target:{closest:q=>q==='[data-private-task-date]'?{dataset:{privateTaskDate:action}}:null}});for(const[name,value]of [['search-query','Plan'],['search-section','School'],['search-priority','High'],['search-status','completed']])s.events.input({target:{name,value}});click('overdue');for(let i=0;i<4;i++)await turn();assert.equal(calls[0].status,'open');assert.equal(calls[0].dateTo,'2026-11-09');assert.equal(calls[0].query,'Plan');assert.equal(calls[0].section,'School');assert.equal(calls[0].priority,'High');click('undated');for(let i=0;i<4;i++)await turn();assert.equal(calls[1].dateStatus,'undated');assert.equal(calls[1].dateFrom,'');assert.equal(calls[1].dateTo,'');click('week');for(let i=0;i<4;i++)await turn();assert.equal(calls[2].dateStatus,'dated');assert.equal(calls[2].dateFrom,'2026-11-10');assert.equal(calls[2].dateTo,'2026-11-16');assert.match(s.root.innerHTML,/Task date shortcuts/);});
test('task date shortcuts cannot replace an open task draft or start a second pending search',async t=>{const s=await setup(t,{...taskSpaceOptions,allowTaskCreate:true}),click=action=>s.events.click({target:{closest:q=>q==='[data-private-task-date]'?{dataset:{privateTaskDate:action}}:null}});let calls=0,release;s.client.search=()=>{calls++;return new Promise(r=>release=r);};s.events.click({target:{closest:q=>q==='#private-task-new'?{}:null}});click('today');assert.equal(calls,0);assert.match(s.root.innerHTML,/private-task-create-form/);s.events.click({target:{closest:q=>q==='#private-task-create-discard'?{}:null}});for(let i=0;i<4;i++)await turn();click('today');click('week');assert.equal(calls,1);s.logout();release({});for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/private-brief-login/);assert.doesNotMatch(s.root.innerHTML,/Task date shortcuts/);});
test('task date shortcuts stay absent from the Daily Brief and Calendar',async t=>{for(const options of [{allowSearch:true,allowSearchDates:true,allowUndatedTasks:true},calendarOptions]){const s=await setup(t,options);assert.doesNotMatch(s.root.innerHTML,/data-private-task-date=/);}});

const quickDateOptions={...taskSpaceOptions,allowTaskQuickDates:true,allowTaskEdit:true,allowTaskCompletion:true};
const clickQuickDate=(s,action)=>s.events.click({target:{closest:q=>q==='[data-private-task-date-review]'?{dataset:{privateTaskDateReview:'E'.repeat(43),taskDateAction:action}}:null}});
async function quickDateSetup(t){const s=await setup(t,quickDateOptions);s.client.search=async f=>({...f,limit:50,offset:0,matchCount:1,omittedRecords:0,dateRangeUnavailableRecords:0,readOnly:true,providerRead:false,checkedAt:'2026-11-10T18:00:00Z',expiresAt:Date.parse('2026-11-10T18:04:00Z'),results:[{type:'task',title:'Fictional dated task',section:'Work',day:'2026-11-10',completed:false,priority:'High',editToken:'E'.repeat(43)}]});s.events.click({target:{closest:q=>q==='#private-brief-refresh'?{}:null}});for(let i=0;i<4;i++)await turn();s.reviewCalls=[];s.saves=0;s.client.reviewTaskEdit=async values=>{s.reviewCalls.push(values);return{reviewId:'R'.repeat(43),title:values.title,day:values.day,section:values.section,priority:'High',expiresAt:Date.parse('2026-11-10T18:04:00Z')};};s.client.saveTaskEdit=async()=>{s.saves++;return{saved:true};};s.client.cancelTaskEdit=async()=>{};return s;}
test('quick task dates prepare metadata-only review and never save until explicit approval',async t=>{const s=await quickDateSetup(t);assert.match(s.root.innerHTML,/Move to tomorrow/);clickQuickDate(s,'tomorrow');for(let i=0;i<4;i++)await turn();assert.equal(s.saves,0);assert.equal(s.reviewCalls.length,1);assert.deepEqual(Object.keys(s.reviewCalls[0]).sort(),['day','editToken','section','title']);assert.equal(s.reviewCalls[0].day,'2026-11-11');assert.match(s.root.innerHTML,/Change this due date/);assert.match(s.root.innerHTML,/2026-11-10 → 2026-11-11/);assert.doesNotMatch(s.root.innerHTML,/Approve completion/);s.events.click({target:{closest:q=>q==='#private-task-approve'?{}:null}});for(let i=0;i<4;i++)await turn();assert.equal(s.saves,1);assert.match(s.root.innerHTML,/Task due date saved/);});
test('clearing a due date requires review and Cancel saves nothing',async t=>{const s=await quickDateSetup(t);let cancels=0;s.client.cancelTaskEdit=async()=>{cancels++;};clickQuickDate(s,'undated');for(let i=0;i<4;i++)await turn();assert.equal(s.reviewCalls[0].day,'');assert.match(s.root.innerHTML,/2026-11-10 → No due date/);s.events.click({target:{closest:q=>q==='#private-task-cancel'?{}:null}});for(let i=0;i<4;i++)await turn();assert.equal(cancels,1);assert.equal(s.saves,0);});
test('quick date review rejects unexpected hidden fields and cannot survive sign-out',async t=>{const s=await quickDateSetup(t);s.client.reviewTaskEdit=async v=>({reviewId:'R'.repeat(43),title:v.title,day:v.day,section:v.section,description:'UNEXPECTED_BODY_CONTENT',expiresAt:Date.parse('2026-11-10T18:04:00Z')});clickQuickDate(s,'tomorrow');for(let i=0;i<4;i++)await turn();assert.doesNotMatch(s.root.innerHTML,/UNEXPECTED_BODY_CONTENT|Approve due date change/);let release;s.client.reviewTaskEdit=()=>new Promise(r=>release=r);clickQuickDate(s,'tomorrow');while(!release)await turn();s.logout();release({});for(let i=0;i<4;i++)await turn();assert.doesNotMatch(s.root.innerHTML,/Change this due date|Fictional dated task/);assert.equal(s.saves,0);});
test('quick due-date actions remain absent unless explicitly enabled',async t=>{const s=await setup(t,taskSpaceOptions);assert.doesNotMatch(s.root.innerHTML,/data-private-task-date-review=/);});
test('unchanged quick date review does not offer saving or call a write',async t=>{const s=await quickDateSetup(t);s.client.reviewTaskEdit=async()=>({noChanges:true});clickQuickDate(s,'tomorrow');for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/already has that due date/);assert.doesNotMatch(s.root.innerHTML,/Approve due date change/);assert.equal(s.saves,0);});
test('repeated due-date approvals cannot start a second uncertain save',async t=>{const s=await quickDateSetup(t);clickQuickDate(s,'tomorrow');for(let i=0;i<4;i++)await turn();let release;s.client.saveTaskEdit=()=>{s.saves++;return new Promise(r=>release=r);};const approve=()=>s.events.click({target:{closest:q=>q==='#private-task-approve'?{}:null}});approve();approve();assert.equal(s.saves,1);s.logout();release({saved:true});for(let i=0;i<4;i++)await turn();assert.doesNotMatch(s.root.innerHTML,/Task due date saved|Fictional dated task/);});

async function noteCopySetup(t){const s=await setup(t,{...notesSpaceOptions,allowNoteCopy:true,allowNoteCreate:true,allowLongNotes:true});s.bodyReads=0;s.creates=0;s.client.readNote=async()=>{s.bodyReads++;return{readOnly:true,title:'Fictional original note',body:'\n  Keep copied spacing.\n\n',expiresAt:Date.parse('2026-11-10T18:04:00Z')};};s.client.reviewNewNote=async values=>{s.copyReview=values;return{reviewId:'C'.repeat(43),title:values.title.trim(),body:values.preserveWhitespace?values.body:values.body.trim(),expiresAt:Date.parse('2026-11-10T18:04:00Z')};};s.client.createNote=async()=>{s.creates++;return{created:true};};s.client.cancelNewNote=async()=>{};s.events.click({target:{closest:q=>q==='[data-private-note]'?{dataset:{privateNote:'N'.repeat(43)}}:null}});for(let i=0;i<4;i++)await turn();return s;}
test('copying an opened note prepares only a new draft and preserves text through review before creation',async t=>{const s=await noteCopySetup(t);assert.match(s.root.innerHTML,/Copy to a new note/);s.events.click({target:{closest:q=>q==='#private-note-copy'?{}:null}});assert.equal(s.bodyReads,1);assert.equal(s.creates,0);assert.match(s.root.innerHTML,/separate note in Personal Life/);assert.match(s.root.innerHTML,/Add a private note/);s.events.submit({target:{id:'private-note-editor'},preventDefault(){}});for(let i=0;i<4;i++)await turn();assert.equal(s.copyReview.preserveWhitespace,true);assert.equal(s.copyReview.body,'\n  Keep copied spacing.\n\n');assert.deepEqual(Object.keys(s.copyReview).sort(),['body','preserveWhitespace','title']);assert.equal(s.creates,0);s.events.click({target:{closest:q=>q==='#private-note-approve'?{}:null}});for(let i=0;i<4;i++)await turn();assert.equal(s.creates,1);assert.equal(s.bodyReads,1);});
test('discarding or signing out of a copied note saves nothing and clears copied text',async t=>{for(const mode of ['discard','logout']){const s=await noteCopySetup(t);s.events.click({target:{closest:q=>q==='#private-note-copy'?{}:null}});if(mode==='discard')s.events.click({target:{closest:q=>q==='#private-note-discard'?{}:null}});else s.logout();for(let i=0;i<4;i++)await turn();assert.equal(s.creates,0);assert.doesNotMatch(s.root.innerHTML,/Keep copied spacing/);}});

