test('saved email can prepare a private task draft without a new read or write; saving remains reviewed',async t=>{const now=Date.parse('2026-11-12T18:00:00Z'),s=await setup(t,{...taskCopyOptions,allowSavedMailRead:true,clock:()=>now}),panel={innerHTML:'',contains:()=>false};s.root.querySelector=q=>q==='#private-saved-mail-panel'?panel:null;let reads=0,writes=0,proposal;s.client.readSavedMail=async()=>{reads++;return{source:'Saved Gmail copies',readOnly:true,snapshot:true,providerRead:false,bodyRead:false,limit:5,offset:0,hasMore:false,browseLimitReached:false,checkedAt:new Date(now).toISOString(),expiresAt:now+300000,records:[{subject:'Fictional deadline tomorrow',sender:'Fictional sender',receivedAt:'2026-11-06T15:00:00Z',savedAt:'2026-11-07T18:00:00Z'}]};};s.client.reviewNewTask=async v=>{proposal=v;return{reviewId:'R'.repeat(43),title:v.title,day:v.day,section:v.section,priority:v.priority,description:v.description,subtasks:[],expiresAt:now+300000};};s.client.createTask=async()=>{writes++;return{created:true};};s.events.click({target:{closest:q=>q==='#private-mail-load'?{}:null}});for(let i=0;i<4;i++)await turn();const token=/data-private-mail-task="([^"]+)"/.exec(panel.innerHTML)[1];s.events.click({target:{closest:q=>q==='[data-private-mail-task]'?{dataset:{privateMailTask:token}}:null}});assert.equal(reads,1);assert.equal(writes,0);assert.match(s.root.innerHTML,/New task draft prepared from the displayed saved email metadata/);assert.match(s.root.innerHTML,/Saved Gmail metadata/);s.events.submit({target:{id:'private-task-create-form'},preventDefault(){}});for(let i=0;i<4;i++)await turn();assert.equal(proposal.title,'Fictional deadline tomorrow');assert.equal(proposal.day,'');assert.equal(proposal.section,'Personal Life');assert.equal(proposal.priority,'Normal');assert.match(proposal.description,/Fictional sender/);assert.equal(Object.hasOwn(proposal,'fromSavedMail'),false);assert.equal(writes,0);s.events.click({target:{closest:q=>q==='#private-task-create-approve'?{}:null}});for(let i=0;i<4;i++)await turn();assert.equal(writes,1);assert.equal(reads,1);});

