async function historicalNoteCorrection(t,{field='both',earlierBody='Earlier exact\n<literal>',earlierTitle='Earlier fictional note'}={}){
 const s=await setup(t,{allowNoteRead:true,allowNoteEdit:true,allowNoteHistory:true});const token='h'.repeat(43),entry={historyReadToken:token,version:1,operation:'UPDATE',capturedAt:'1970-01-01T00:00:00.001Z'},page={readOnly:true,available:true,expiresAt:300001,offset:0,limit:50,matchCount:1,versions:[entry]};let writes=0,proposal;
 s.client.readNote=async()=>({title:'Current fictional note',body:'Current exact text',readOnly:true,expiresAt:300001});s.client.noteHistoryList=async()=>page;s.client.noteHistoryRead=async()=>({readOnly:true,historical:true,expiresAt:300001,version:1,operation:'UPDATE',capturedAt:entry.capturedAt,wasDeleted:false,record:{title:earlierTitle,body:earlierBody}});s.client.reviewNote=async fields=>{proposal=structuredClone(fields);return{reviewId:'fixture',title:fields.title,body:fields.body,expiresAt:300001};};s.client.saveNote=async()=>{writes++;throw Error('Uncertain note save. Keep this draft.');};
 const click=(selector,value)=>s.events.click({target:{closest:q=>q===selector?(value?{dataset:value,getAttribute:()=>value.token}:{}):null}}),settle=async()=>{for(let i=0;i<5;i++)await turn();};
 click('[data-private-note]',{privateNote:'n'.repeat(43)});await settle();assert.match(s.root.innerHTML,/Browse saved versions/);click('#private-note-history-refresh');await settle();click('[data-note-history-read]',{token});await settle();assert.match(s.root.innerHTML,/Current exact text/);assert.equal(writes,0);
 click('#private-note-history-use'+(field==='both'?'':'-'+field));assert.match(s.root.innerHTML,/private-note-editor/);s.events.submit({target:{id:'private-note-editor'},preventDefault(){}});await settle();assert.equal(writes,0);assert.equal(proposal.title,field==='body'?'Current fictional note':earlierTitle);assert.equal(proposal.body,field==='title'?'Current exact text':earlierBody);assert.equal(proposal.noteToken,'n'.repeat(43));assert.match(s.root.innerHTML,/Approve note save/);click('#private-note-approve');await settle();assert.equal(writes,1);assert.match(s.root.innerHTML,/Keep this draft/);assert.match(s.root.innerHTML,field==='title'?/Current exact text/:/Earlier exact\n&lt;literal&gt;/);assert.doesNotMatch(s.root.innerHTML,/Approve note save/);
}
test('opened note history hands earlier exact text to original reviewed editor and retains uncertain-save draft',async t=>historicalNoteCorrection(t));
test('reuse only the earlier body even when the historical title exceeds the current editor limit',async t=>{
 await historicalNoteCorrection(t,{field:'body',earlierTitle:'x'.repeat(130)});
});
test('reuse only the earlier title even when the historical body exceeds the current editor limit',async t=>{
 await historicalNoteCorrection(t,{field:'title',earlierBody:'x'.repeat(11000)});
});

