test('earlier due-date correction starts from the current task and requires its original review',async t=>{
 const s=await historicalTaskCorrection(t,{dueDateOnly:true});
 assert.equal(s.managed(),1);
 assert.match(s.root.innerHTML,/Only the earlier due date is proposed/);
 let proposed;
 s.client.reviewTaskEdit=async fields=>{
  proposed=fields;
  return {...Object.fromEntries(['title','description','day','section','priority'].map(key=>[key,fields[key]])),subtasks:[{title:'Current exact step',done:true}],removedSubtasks:[],addedSubtaskCount:0,reviewId:'fixture',expiresAt:300001};
 };
 let saves=0;
 s.client.saveTaskEdit=async()=>{saves++;return {saved:true};};
 s.review();await s.settle();
 assert.deepEqual([proposed.day,proposed.title,proposed.description,proposed.section,proposed.priority],['2026-11-19','Current fictional task','Current exact task description','Work','Normal']);
 assert.deepEqual(Array.from(proposed.subtaskTitles),['Current exact step']);
 assert.deepEqual(Array.from(proposed.subtaskStates),[true]);
 assert.doesNotMatch(JSON.stringify(proposed),/historical|recurrence|omittedSubtasks/);
 assert.equal(saves,0);
 assert.match(s.root.innerHTML,/Approve task changes/);
 s.click('#private-task-create-approve');await s.settle();
 assert.equal(saves,1);
});

