 const now=Date.parse('2026-11-19T17:00:00Z');
 const options={allowManualFinance:true,allowManualBills:true,allowBriefLayout:true,clock:()=>now,briefReader:async()=>narrativeSnapshot(now)};
 const off=await setup(t,options);
 assert.doesNotMatch(off.root.innerHTML,/private-brief-bills-open/);
